from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            max_sum = 9 * len(digits)
            total = 0

            for target_sum in range(1, max_sum + 1):
                @lru_cache(None)
                def dp(pos: int, cur_sum: int, prod_mod: int, tight: bool, started: bool) -> int:
                    if cur_sum > target_sum:
                        return 0

                    if pos == len(digits):
                        return int(started and cur_sum == target_sum and prod_mod == 0)

                    limit = digits[pos] if tight else 9
                    ans = 0

                    for d in range(limit + 1):
                        next_tight = tight and (d == limit)

                        if not started and d == 0:
                            ans += dp(pos + 1, cur_sum, 1 % target_sum, next_tight, False)
                        else:
                            next_sum = cur_sum + d
                            if next_sum <= target_sum:
                                next_prod = (prod_mod * d) % target_sum
                                ans += dp(pos + 1, next_sum, next_prod, next_tight, True)

                    return ans

                total += dp(0, 0, 1 % target_sum, True, False)

            return total

        return count_up_to(r) - count_up_to(l - 1)
